import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String s = scanner.nextLine();
        int a = s.substring(1, s.length() - 1).indexOf("dot");

        while (a != -1) {
            s = s.substring(0, a + 1) + '.' + s.substring(a + 4);
            a = s.substring(1, s.length() - 1).indexOf("dot");
        }

        a = s.substring(1, s.length() - 1).indexOf("at");
        s = s.substring(0, a + 1) + '@' + s.substring(a + 3);

        System.out.println(s);
    }
}
